from pathlib import Path
import re, json

root=Path(__file__).resolve().parent.parent
introtext=(root/'audit-extraction-intro-translation-2026-10-11'/'2025-06-23_intro training group ½ (3).txt').read_text(encoding='utf-8')
intro=re.findall(r'^\d+\. (.+)$',introtext.split('Part 2:')[0],re.M)[-15:]
it=(root/'2026-10-11-rephrase-indicator-extracts'/'indicator-worksheet.txt').read_text(encoding='utf-8')
parts=re.split(r'Part [123]',it)[1:]
ids=[re.findall(r'^\d+\. (.+)$',p,re.M) for p in parts]
rt=(root/'2026-10-11-rephrase-indicator-extracts'/'rephrase-worksheet.txt').read_text(encoding='utf-8')
rp=[re.sub(r'\s+',' ',s).strip() for s in re.findall(r'Q\d+\. Statement:\s*(.*?)\s*If/Then:',rt,re.S)]
tt=(root/'audit-extraction-intro-translation-2026-10-11'/'2025-07-03_Homework For Group 1 & Group 2 (1).txt').read_text(encoding='utf-8')
tt=re.sub(r'=== PAGE \d+ ===','',tt)
tr=[re.sub(r'\s+',' ',s).strip() for s in re.findall(r'Statement \d+\s*(.*?)\s*Conditional Relationship:',tt,re.S)]
assert [len(intro),*[len(a) for a in ids],len(rp),len(tr)]==[15,13,10,20,25,35]
drills=[
dict(title='Find the indicator and both conditions',short='Intro training',stage='Recognize',source='Intro training · Part 1',items=intro,mode='identify',instruction='Read each statement. Write the indicator expression, then identify the complete sufficient and necessary conditions. Keep words that limit who, when, or what the rule covers.'),
dict(title='Recognize Group 1 and Group 2',short='Indicator identification',stage='Recognize',source='Indicator ID · Part 1',items=ids[0],mode='group',instruction='Find the indicator expression in each statement. Identify its group and explain which condition it helps you locate. If you identify more than one expression, label each separately.'),
dict(title='Put the conditions beside the arrow',short='Intro training revisited',stage='Diagram',source='Intro training · Part 2',items=intro,mode='diagram',instruction='Return to the 15 intro statements. Put the sufficient condition on the left and the necessary condition on the right. After learning contraposition, expand the optional second step.'),
dict(title='Identify each side of the rule',short='Diagramming and roles',stage='Diagram',source='Indicator ID · Part 2',items=ids[1],mode='roles',instruction='Identify the full sufficient condition and the full necessary condition. Write them beside the arrow, even when the sentence gives them in a different order.'),
dict(title='Rewrite the rule as if / then',short='Conditional rephrasing',stage='Translate',source='If-Then rephrase · Questions 1–25',items=rp,mode='rephrase',instruction='Rewrite each statement as “If …, then …” without changing its meaning. Name the indicators you used. Keep permission, requirements, deadlines, and restrictions in your wording.'),
dict(title='Translate, contrapose, and read back',short='Four ways to express the rule',stage='After contraposition',source='Indicator ID · Part 3',items=ids[2],mode='full',instruction='Write the original arrow, its contrapositive, and both in ordinary if/then language. Negate the whole condition, including any restriction. Complete this set after the contrapositive lesson.'),
dict(title='Practice independent translation',short='The complete translation set',stage='After contraposition',source='Translation set (burrito) · Statements 1–35',items=tr,mode='translation',instruction='Treat each statement as the supplied rule. Diagram its conditional relationship, then write its contrapositive. Keep every qualifier and define any abbreviation you use. Later items include negative and compound conditions.')]
flags={0:{2:'The key strengthens “expect thunder” to “thunder will follow.” Preserve the expectation.',4:'Preserve the training requirement; a duty does not prove actual compliance.',5:'Keep “student who maintains a 4.0 GPA.”',8:'Keep membership and “can attend.”',9:'“Should be evacuated” is an obligation, not proof of evacuation.',13:'Keep the applicant restriction.'},1:{4:'The source key conflicts over the classification of “the only.”',8:'The borrowing/collateral wording needs clarification before grading.',11:'This is an instruction. Do not treat it as proof of actual compliance.'},3:{6:'The key incorrectly turns a collateral requirement into a guaranteed loan.',10:'Keep “before” and distinguish an instruction from actual compliance.'},4:{1:'Mixed indicators and obligation: do not force one group label.',4:'“Only key” does not exclude non-key ways of opening the door.',6:'Mixed indicators and obligation: preserve the duty.',7:'Allow a separate group label for each indicator.',8:'Preserve “can apply.”',11:'Keep the legally-binding restriction; classify each expression separately.',18:'Keep “currently active”; negate the whole qualified signing condition.',19:'Keep the file assigned to this requester.',20:'Allow both indicators; preserve requirement status.',25:'Keep the matching transaction record and classify expressions separately.'},5:{8:'Keep “can occur” and “first.”',9:'The key changes a requirement into completed maintenance.',12:'Keep “before”; this instruction needs a compliance-rule frame.',15:'Negate the whole three-reviewer condition.',16:'Not both does not mean neither.',18:'Keep “can be processed.”'},6:{3:'Named comparison is unclear in the source.',10:'The key explanation conflicts with its correctly directed arrow.',20:'The key incorrectly uses “Always” as a condition. This needs an explicit domain.',25:'Negate the whole conjunction: not both does not mean neither.',27:'Keep the whole compound condition.',28:'The key misses the exclusivity direction. Adjudicate the natural-language claim.',29:'Preserve “can be conceptualized.”',31:'“Plant soil decreases” is unclear. Preserve this source for review; do not grade it.',33:'The key misidentifies “will” and drops the timing.',35:'Negate the whole qualified duty claim.'}}
flags[2]=flags[0]
for i,d in enumerate(drills):d['flags']=flags.get(i,{})
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conditional logic · Drill collection</title><style>
:root{--ink:#183340;--muted:#526773;--paper:#f5f2eb;--line:#ccd4cd;--teal:#176454;--gold:#bf704b}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.6 system-ui,sans-serif}a{color:inherit}button,input,textarea,select{font:inherit}button,a.button{cursor:pointer;border:1px solid var(--line);border-radius:7px;background:#fffdf7;color:var(--ink);padding:11px 17px;text-decoration:none;display:inline-block}button:hover,a.button:hover{border-color:var(--teal);background:#edf4ed}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #bf704b;outline-offset:4px}h1,h2,h3{font-family:Georgia,serif;font-weight:400;line-height:1.14}h1{font-size:clamp(38px,5vw,64px);margin:18px 0 24px;letter-spacing:-1.5px}h2{font-size:30px;margin:10px 0 20px}h3{font-size:25px;margin:12px 0}.top{background:var(--ink);color:#fff9eb;padding:18px 5vw;display:flex;justify-content:space-between;gap:20px;align-items:center}.top a{text-decoration:none;font-family:Georgia,serif;font-size:23px}.top small{font-size:13px;letter-spacing:1px}.shell{max-width:1230px;margin:auto;padding:48px 36px 80px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;font-weight:700;color:var(--teal)}.intro{display:grid;grid-template-columns:1.5fr 1fr;gap:65px;align-items:center;margin-bottom:40px}.lede{font-size:20px;max-width:720px}.summary{border-left:1px solid var(--line);padding:24px 0 24px 35px}.summary strong{font:50px Georgia,serif}.summary p{margin:12px 0}.notice{color:var(--muted);font-size:15px}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.card{background:#fffdf8;border:1px solid var(--line);border-radius:12px;padding:26px 28px;display:block;text-decoration:none;transition:transform .2s,border-color .2s}.card:hover{transform:translateY(-3px);border-color:var(--teal)}.card:first-child{background:var(--ink);color:#fff9eb;grid-column:1/-1;display:grid;grid-template-columns:110px 1fr;gap:20px}.card:first-child .eyebrow,.card:first-child .cardmeta{color:#c3dacf}.number{font:italic 46px Georgia;color:var(--gold)}.cardmeta{font-size:14px;color:var(--muted);display:flex;justify-content:space-between;gap:12px;margin-top:22px}.bar{height:4px;background:#dfe4dc;border-radius:10px;margin-top:16px;overflow:hidden}.bar i{display:block;height:100%;background:var(--teal)}.toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;justify-content:space-between;margin:28px 0}.toolbar label{display:flex;align-items:center;gap:8px;font-size:15px}.drillintro{max-width:900px}.track{display:flex;gap:7px;margin:24px 0}.track a{flex:1;height:8px;background:#d3dbd1;border-radius:5px}.track a.active{background:var(--teal)}.questions{display:grid;gap:18px}.question{background:#fffdf8;border:1px solid var(--line);border-radius:10px;overflow:hidden}.question>summary{padding:25px 28px;cursor:pointer;list-style:none;display:grid;grid-template-columns:44px 1fr 22px;gap:16px;align-items:start}.question>summary::-webkit-details-marker{display:none}.question>summary:after{content:'+';font-size:25px;color:var(--teal)}.question[open]>summary:after{content:'−'}.qnum{font-size:13px;color:var(--teal);padding-top:5px}.stem{font:23px/1.45 Georgia,serif}.workspace{border-top:1px solid var(--line);margin:0 28px;padding:26px 0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:22px}.field{display:block;font-size:14px;font-weight:600}.field.wide{grid-column:1/-1}textarea,input[type=text],select{width:100%;margin-top:9px;background:#fffefb;border:1px solid #b8c7bf;border-radius:6px;color:var(--ink);padding:12px;font-size:17px;font-weight:400;resize:vertical}textarea{min-height:90px}.arrowrow{display:grid;grid-template-columns:1fr 45px 1fr;gap:15px;align-items:center}.arrow{font-size:32px;text-align:center;color:var(--teal);padding-top:28px}.optional{margin-top:22px}.optional>summary{cursor:pointer;font-weight:600}.editorial{border-left:3px solid var(--gold);padding:10px 16px;margin:0 0 22px;background:#fff2e6;font-size:15px}.reviewer-note{display:none}.review-on .reviewer-note{display:block}.bottom{display:flex;justify-content:space-between;gap:20px;margin-top:38px}.badge{font-size:12px;border:1px solid currentColor;border-radius:20px;padding:3px 9px}.source{font-size:13px;color:var(--muted);margin-top:22px}footer{border-top:1px solid var(--line);padding-top:22px;margin-top:45px;color:var(--muted);font-size:14px}input[type=checkbox]{width:18px;height:18px;accent-color:var(--teal)}@media(max-width:700px){.shell{padding:28px 18px 60px}.intro{grid-template-columns:1fr;gap:10px}.summary{border-left:0;border-top:1px solid var(--line);padding:20px 0}.cards{grid-template-columns:1fr}.card:first-child{grid-template-columns:55px 1fr}.card{padding:22px}.fields{grid-template-columns:1fr}.field.wide{grid-column:auto}.question>summary{padding:20px 16px;grid-template-columns:26px 1fr 14px;gap:8px}.workspace{margin:0 16px}.stem{font-size:21px}.arrowrow{grid-template-columns:1fr}.arrow{padding:0;transform:rotate(90deg)}.top small{display:none}.bottom{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}@media print{.top,.toolbar,.bottom,button,.track{display:none}.shell{padding:0}.question{break-inside:avoid}.reviewer-note{display:none!important}}
</style></head><body><header class="top"><a href="#all">Conditional logic</a><small>GROUP 1 & GROUP 2 · WORKSHEET PROTOTYPE</small></header><main class="shell" id="app"></main><script>
const drills=__DATA__;
const app=document.getElementById('app');let saved={},saveAvailable=true,review=false;
try{saved=JSON.parse(localStorage.getItem('conditional-drill-prototype-v1')||'{}')}catch(e){saveAvailable=false}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const done=(i)=>drills[i].items.filter((s,j)=>Object.keys(saved).some(k=>k.startsWith(i+'-'+j+'-')&&String(saved[k]).trim())).length;
function field(i,j,key,label,wide=false){const id=i+'-'+j+'-'+key;return `<label class="field ${wide?'wide':''}" for="${id}">${label}<textarea id="${id}" data-key="${id}" rows="2">${esc(saved[id]||'')}</textarea></label>`}
function diagram(i,j,prefix=''){return `<div class="arrowrow">${field(i,j,prefix+'left','Left · Sufficient condition')}<span class="arrow" aria-hidden="true">→</span>${field(i,j,prefix+'right','Right · Necessary condition')}</div>`}
function work(d,i,j){let content='';if(d.mode==='identify'){content=`<div class="fields">${field(i,j,'indicator','Indicator expression',true)}${field(i,j,'sufficient','Complete sufficient condition')}${field(i,j,'necessary','Complete necessary condition')}</div>`}else if(d.mode==='group'){content=`<div class="fields">${field(i,j,'indicator','Indicator expression')}${field(i,j,'group','Group and condition it identifies')}</div>`}else if(d.mode==='diagram'||d.mode==='roles'){content=diagram(i,j);if(d.mode==='diagram')content+=`<details class="optional"><summary>After contraposition: write the contrapositive</summary>${field(i,j,'contra','Contrapositive',true)}</details>`}else if(d.mode==='rephrase'){content=`<div class="fields">${field(i,j,'ifthen','If …, then …',true)}${field(i,j,'indicator','Indicator expression(s)')}${field(i,j,'groups','Group for each expression')}</div><details class="optional"><summary>After contraposition: rewrite the contrapositive</summary>${field(i,j,'contra','Contrapositive in ordinary language',true)}</details>`}else if(d.mode==='full'){content=`<div class="fields">${field(i,j,'original','Original diagram')}${field(i,j,'contra','Contrapositive diagram')}${field(i,j,'ifthen','Original in if/then form')}${field(i,j,'contrawords','Contrapositive in if/then form')}</div>`}else content=`<div class="fields">${field(i,j,'original','Conditional relationship')}${field(i,j,'contra','Contrapositive')}</div>`;return content}
function render(){let match=location.hash.match(/^#drill-(\d+)$/),i=match?Number(match[1])-1:-1;if(i<0||i>=drills.length){app.innerHTML=`<section class="intro"><div><span class="eyebrow">A progression to review together</span><h1>Seven drills.<br>One connected path.</h1><p class="lede">Start with the intro training. Find the conditions, place them beside the arrow, then translate the whole rule.</p></div><aside class="summary"><strong>133</strong><p>worksheet tasks across seven separate drill pages.</p><p class="notice">All original statements are included. Some return for a new task. This is a writing prototype, not an automatically graded quiz.</p></aside></section><div class="cards">${drills.map((d,n)=>`<a class="card" href="#drill-${n+1}"><div class="number">${String(n+1).padStart(2,'0')}</div><div><span class="eyebrow">${esc(d.stage)} · Drill ${n+1}</span><h2>${esc(d.title)}</h2><p>${esc(d.short)}</p><div class="cardmeta"><span>${d.items.length} questions · ${done(n)} started</span><span>Open drill →</span></div><div class="bar"><i style="width:${done(n)/d.items.length*100}%"></i></div></div></a>`).join('')}</div><footer>Original statements from your Group 1 and 2 teaching materials. The sequence and response spaces are adapted for review. Answer keys have not been imported because the source audit identified corrections.<br><span id="save-status">${saveAvailable?'Responses stay in this browser on this device.':'Browser saving is unavailable; responses last for this open page.'}</span></footer>`;return}let d=drills[i];app.innerHTML=`<a class="button" href="#all">← All seven drills</a><div class="track" aria-label="Drill sequence">${drills.map((x,n)=>`<a href="#drill-${n+1}" class="${i===n?'active':''}" aria-label="Drill ${n+1}: ${esc(x.title)}" ${i===n?'aria-current="page"':''}></a>`).join('')}</div><section class="drillintro"><span class="eyebrow">Drill ${i+1} / 7 · ${esc(d.stage)}</span><h1>${esc(d.title)}</h1><p class="lede">${esc(d.instruction)}</p></section><div class="toolbar"><span id="progress">${done(i)} of ${d.items.length} responses started</span><div><button id="expand">Open all questions</button> <button id="collapse">Close all questions</button></div><label><input id="review" type="checkbox" ${review?'checked':''}> Source review notes</label></div><div class="questions ${review?'review-on':''}">${d.items.map((s,j)=>`<details class="question" ${j===0?'open':''}><summary><span class="qnum">${String(j+1).padStart(2,'0')}</span><span class="stem">${esc(s)}</span></summary><div class="workspace">${d.flags[j+1]?`<aside class="editorial reviewer-note"><strong>Source review · Item ${j+1}</strong><br>${esc(d.flags[j+1])}</aside>`:''}${work(d,i,j)}<p class="source">${esc(d.source)} · Original item ${j+1}</p></div></details>`).join('')}</div><nav class="bottom" aria-label="Between drills">${i>0?`<a class="button" href="#drill-${i}">← Drill ${i}</a>`:'<a class="button" href="#all">All drills</a>'}${i<6?`<a class="button" href="#drill-${i+2}">Drill ${i+2} →</a>`:'<a class="button" href="#all">Back to the collection →</a>'}</nav><footer>Draft responses, not graded. Source wording is preserved for comparison. Open “Source review notes” to see items needing correction before student use.<br><span id="save-status">${saveAvailable?'Responses stay in this browser on this device.':'Browser saving is unavailable; responses last for this open page.'}</span></footer>`;document.getElementById('expand').onclick=()=>document.querySelectorAll('.question').forEach(q=>q.open=true);document.getElementById('collapse').onclick=()=>document.querySelectorAll('.question').forEach(q=>q.open=false);document.getElementById('review').onchange=e=>{review=e.target.checked;document.querySelector('.questions').classList.toggle('review-on',review)};app.querySelectorAll('textarea').forEach(el=>el.addEventListener('input',()=>{saved[el.dataset.key]=el.value;try{localStorage.setItem('conditional-drill-prototype-v1',JSON.stringify(saved))}catch(e){saveAvailable=false;document.getElementById('save-status').textContent='Browser saving is unavailable; responses last for this open page.'}document.getElementById('progress').textContent=done(i)+' of '+d.items.length+' responses started'}))}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
</script></body></html>'''.replace('__DATA__',json.dumps(drills,ensure_ascii=False))
(root/'prototype'/'group-1-2-drills.html').write_text(html,encoding='utf-8')
print('Built',sum(len(d['items']) for d in drills),'items in',len(drills),'drills')

